package dev.irisvisualizer.editor;

import java.nio.file.*;
import java.nio.file.attribute.DosFileAttributeView;
import java.util.*;

final class ResourceRemovalSaveTests {
    private static void check(boolean value,String message){ResourceOperationTests.check(value,message);}
    static void run(Path temp)throws Exception{
        var pack=ResourceOperationTests.fixture();Path root=temp.resolve("resource-rename-save");pack.save(root);byte[] old=Files.readAllBytes(root.resolve("jigsaw-pools/alpha.json"));ResourceOperationTests.apply(pack,ResourceOperation.Mode.RENAME,"jigsaw-pools/alpha.json","beta");check(Files.exists(root.resolve("jigsaw-pools/alpha.json")) && !Files.exists(root.resolve("jigsaw-pools/beta.json")),"Apply makes no disk writes or deletions");var cache=new WorkspaceChanges.Cache();var all=cache.query(pack,new WorkspaceChanges.Query("",WorkspaceChanges.Filter.ALL));check(all.removedFiles()==1 && all.modifiedFiles()==2 && all.newFiles()==1 && all.total()==4,"pending inventory separately counts old path, new path and reference rewrites");var removed=pack.pendingChanges().stream().filter(e->e.kind()==WorkspaceChanges.Kind.REMOVED_FILE).findFirst().orElseThrow();check(cache.query(pack,new WorkspaceChanges.Query("",WorkspaceChanges.Filter.REMOVED_FILES)).entries().equals(List.of(removed)) && cache.check(pack,removed).status()==WorkspaceChanges.Status.REMOVAL_READY,"removed-file filter and saved-hash advisory review");var report=PendingDiskReview.inspect(pack.capturePendingDiskReview(null),()->false,(a,b)->{});check(report.checks().stream().anyMatch(c->c.entry().equals(removed) && c.status()==WorkspaceChanges.Status.REMOVAL_READY),"background disk review understands pending file removals");
        pack.saveCopy(temp.resolve("resource-rename-copy"));pack.exportZip(temp.resolve("resource-rename.zip"));check(Files.exists(root.resolve("jigsaw-pools/alpha.json")) && !Files.exists(temp.resolve("resource-rename-copy/jigsaw-pools/alpha.json")) && !PackWorkspace.importZip(temp.resolve("resource-rename.zip")).paths().contains("jigsaw-pools/alpha.json") && pack.dirty(),"Copy/ZIP omit removed path without modifying active folder or clearing pending changes");
        pack.save(root);check(!Files.exists(root.resolve("jigsaw-pools/alpha.json")) && Files.exists(root.resolve("jigsaw-pools/beta.json")) && !pack.dirty(),"Save publishes replacements and then deletes old path");var reopened=PackWorkspace.open(root);for(String path:pack.paths())check(Arrays.equals(pack.read(path),reopened.read(path)),"saved rename/ref updates exact round trip");
        // Every baseline is preflighted before any writes; changed source refuses deletion and all publication.
        var conflict=ResourceOperationTests.fixture();Path conflictRoot=temp.resolve("resource-removal-conflict");conflict.save(conflictRoot);ResourceOperationTests.apply(conflict,ResourceOperation.Mode.RENAME,"jigsaw-pools/alpha.json","beta");byte[] references=Files.readAllBytes(conflictRoot.resolve("structures/start.json"));Files.write(conflictRoot.resolve("jigsaw-pools/alpha.json"),ResourceOperationTests.bytes("external"));ResourceOperationTests.rejects(()->conflict.save(conflictRoot));check(!Files.exists(conflictRoot.resolve("jigsaw-pools/beta.json")) && Arrays.equals(references,Files.readAllBytes(conflictRoot.resolve("structures/start.json"))) && conflict.dirty(),"old-source conflict blocks all writes before publication");
        Files.write(conflictRoot.resolve("jigsaw-pools/alpha.json"),old);conflict.save(conflictRoot);check(!conflict.dirty(),"explicit retry succeeds after baseline restored");
        // A late removal failure can leave new destinations saved; the tombstone and exact baselines remain retryable.
        var partial=ResourceOperationTests.fixture();Path partialRoot=temp.resolve("resource-removal-partial");partial.save(partialRoot);ResourceOperationTests.apply(partial,ResourceOperation.Mode.RENAME,"jigsaw-pools/alpha.json","beta");long saved=partial.saveRevision();ResourceOperationTests.rejects(()->partial.save(partialRoot,FileSaves::write,plan->{throw new java.io.IOException("injected before deletion");}));check(partial.saveRevision()>saved && partial.dirty() && Files.exists(partialRoot.resolve("jigsaw-pools/beta.json")) && Files.exists(partialRoot.resolve("jigsaw-pools/alpha.json")),"partial Save records completed writes and retains old path/removal for explicit retry");partial.save(partialRoot);check(!partial.dirty() && !Files.exists(partialRoot.resolve("jigsaw-pools/alpha.json")),"partial retry completes without lost source or foreign overwrite");
        // Global removal authority carries identity/metadata across intervening writes, including equal-byte replacement.
        var late=ResourceOperationTests.fixture();Path lateRoot=temp.resolve("resource-removal-late");late.save(lateRoot);ResourceOperationTests.apply(late,ResourceOperation.Mode.RENAME,"jigsaw-pools/alpha.json","beta");ResourceOperationTests.rejects(()->late.save(lateRoot,FileSaves::write,plan->FileSaves.remove(plan,file->{Path incoming=file.resolveSibling("fixture-external-replacement");Files.write(incoming,old,StandardOpenOption.CREATE_NEW);Files.move(incoming,file,StandardCopyOption.REPLACE_EXISTING);})));check(Files.exists(lateRoot.resolve("jigsaw-pools/alpha.json")) && late.dirty(),"same-byte replacement of preflighted source is not deleted");late.save(lateRoot);check(!late.dirty(),"new explicit preflight can accept the current equal-byte source");
        // A previously absent deletion destination cannot delete a file that appears later.
        var absent=ResourceOperationTests.fixture();Path absentRoot=temp.resolve("resource-removal-absent");absent.save(absentRoot);ResourceOperationTests.apply(absent,ResourceOperation.Mode.DELETE,"images/source.png",null);Files.delete(absentRoot.resolve("images/source.png"));ResourceOperationTests.rejects(()->absent.save(absentRoot,FileSaves::write,plan->FileSaves.remove(plan,file->Files.write(file,new byte[]{0,-1,9},StandardOpenOption.CREATE_NEW))));check(Files.exists(absentRoot.resolve("images/source.png")) && absent.dirty(),"appeared file at absent pending-removal destination is preserved");absent.save(absentRoot);check(!Files.exists(absentRoot.resolve("images/source.png")),"explicit retry after recheck deletes intended source");
        // Read-only source metadata and nonregular/link replacements are preserved rather than force-deleted.
        var readonly=ResourceOperationTests.fixture();Path readonlyRoot=temp.resolve("resource-removal-readonly");readonly.save(readonlyRoot);ResourceOperationTests.apply(readonly,ResourceOperation.Mode.DELETE,"images/source.png",null);Path image=readonlyRoot.resolve("images/source.png");var dos=Files.getFileAttributeView(image,DosFileAttributeView.class,LinkOption.NOFOLLOW_LINKS);if(dos!=null){dos.setReadOnly(true);try{ResourceOperationTests.rejects(()->readonly.save(readonlyRoot));check(Files.exists(image),"read-only source not deleted");}finally{dos.setReadOnly(false);}}readonly.save(readonlyRoot);
        var directory=ResourceOperationTests.fixture();Path dirRoot=temp.resolve("resource-removal-directory");directory.save(dirRoot);ResourceOperationTests.apply(directory,ResourceOperation.Mode.DELETE,"images/source.png",null);Path replaced=dirRoot.resolve("images/source.png");Files.delete(replaced);Files.createDirectory(replaced);Files.write(replaced.resolve("foreign"),new byte[]{7});ResourceOperationTests.rejects(()->directory.save(dirRoot));check(Files.exists(replaced.resolve("foreign")),"nonrecursive deletion never removes replacement directory contents");
        var linked=ResourceOperationTests.fixture();Path linkRoot=temp.resolve("resource-removal-link");linked.save(linkRoot);ResourceOperationTests.apply(linked,ResourceOperation.Mode.DELETE,"images/source.png",null);Path link=linkRoot.resolve("images/source.png"),outside=temp.resolve("resource-removal-external.png");Files.write(outside,new byte[]{0,-1,9});Files.delete(link);boolean links=false;try{Files.createSymbolicLink(link,outside);links=true;}catch(java.io.IOException|UnsupportedOperationException unavailable){}if(links)try{ResourceOperationTests.rejects(()->linked.save(linkRoot));check(Files.isSymbolicLink(link) && Arrays.equals(Files.readAllBytes(outside),new byte[]{0,-1,9}),"symlink replacement and external target preserved");}finally{Files.delete(link);}
        // Pending deleted file + its empty folder are saved in file-before-folder order.
        var folders=ResourceOperationTests.fixture();folders.createSubfolder("images","nested");String moved=ResourceOperationTests.apply(folders,ResourceOperation.Mode.MOVE,"images/source.png","images/nested");Path folderRoot=temp.resolve("resource-removal-folder");folders.save(folderRoot);ResourceOperationTests.apply(folders,ResourceOperation.Mode.DELETE,moved,null);folders.deleteEmptyFolder("images/nested");var folderReview=PendingDiskReview.inspect(folders.capturePendingDiskReview(null),()->false,(a,b)->{});check(folderReview.checks().stream().filter(c->c.entry().kind()==WorkspaceChanges.Kind.REMOVED_FOLDER).allMatch(c->c.status()==WorkspaceChanges.Status.REMOVAL_READY),"pending removed children are understood by folder advisory checks");folders.save(folderRoot);check(!Files.exists(folderRoot.resolve("images/nested")) && !folders.dirty(),"saved deletion followed by nonrecursive empty-folder removal");
        // Pending names stay reserved until Save; Save As leaves the old active folder intact.
        var reservation=ResourceOperationTests.fixture();Path reservationRoot=temp.resolve("resource-removal-reservation");reservation.save(reservationRoot);ResourceOperationTests.apply(reservation,ResourceOperation.Mode.RENAME,"objects/shape.iob","new_shape");ResourceOperationTests.rejects(()->reservation.reviewResourceOperation(ResourceOperation.Mode.RENAME,"objects/new_shape.iob","shape"));reservation.saveAs(temp.resolve("resource-removal-new-active"));check(Files.exists(reservationRoot.resolve("objects/shape.iob")) && !Files.exists(temp.resolve("resource-removal-new-active/objects/shape.iob")) && !reservation.dirty(),"fresh-folder adoption does not delete from previous folder");
        // No old-byte backup, recovery or staging files remain after successful operations.
        try(var paths=Files.walk(root)){check(paths.noneMatch(path->path.getFileName().toString().startsWith(FileSaves.TEMPORARY_PREFIX)),"no staging residue or recovery copies");}
        System.out.println("PASS: resource-operation pending file removals with separate inventory/filter/disk-review counts, baseline/identity/permission-bound nonrecursive Save deletion after reference/destination publication, complete preflight and same-byte/absent/readonly/directory conflict protection, partial-save receipts and explicit retry, file-before-empty-folder removal, pending-name reservation and exact Copy/As/ZIP without old-byte backups or recovery files");
    }
}
